        if (!is_array($php)) {
            return null;
        }
        $min = $php['min'] ?? null;
        $max = $php['max'] ?? null;
        if (!is_string($min) || !is_string($max)) {
            return null;
        }
        return ['min' => $min, 'max' => $max];
    }

    /**
