        $onDay = new DateTimeImmutable($on->format('Y-m-d'));
        $eolDay = new DateTimeImmutable($securityUntil->format('Y-m-d'));
        $interval = $onDay->diff($eolDay);
        $days = $interval->days;
        return $interval->invert === 1 ? -$days : $days;
